from dataclasses import dataclass
from datetime import datetime

from sqlalchemy import DateTime, Integer, String, Text
from sqlalchemy.orm import Mapped, mapped_column

from opentakserver.extensions import db
from opentakserver.functions import iso8601_string_from_datetime


@dataclass
class MissionTask(db.Model):
    __tablename__ = "mission_tasks"

    id: Mapped[int] = mapped_column(Integer, primary_key=True)
    uid: Mapped[str] = mapped_column(String(255), unique=True, nullable=False)
    mission_name: Mapped[str] = mapped_column(String(255), nullable=False)
    title: Mapped[str] = mapped_column(String(255), nullable=False)
    body: Mapped[str] = mapped_column(Text, nullable=True)
    assignee: Mapped[str] = mapped_column(String(255), nullable=True)
    sector_uid: Mapped[str] = mapped_column(String(255), nullable=True)
    return_by: Mapped[datetime] = mapped_column(DateTime, nullable=True)
    status: Mapped[str] = mapped_column(String(32), nullable=False, default="issued")
    created_by: Mapped[str] = mapped_column(String(255), nullable=True)
    created: Mapped[datetime] = mapped_column(DateTime, nullable=True)
    updated: Mapped[datetime] = mapped_column(DateTime, nullable=True)

    def _return_by_naive(self):
        if not self.return_by:
            return None
        rb = self.return_by
        if getattr(rb, "tzinfo", None):
            return rb.replace(tzinfo=None)
        return rb

    def seconds_to_return(self):
        rb = self._return_by_naive()
        if not rb:
            return None
        return int((rb - datetime.utcnow()).total_seconds())

    def due_state(self, warn_seconds: int = 1800):
        """none | ok | warn | overdue | closed — for HQ timer / alerts."""
        st = self.status or "issued"
        if st in ("done", "cancelled"):
            return "closed"
        secs = self.seconds_to_return()
        if secs is None:
            return "none"
        if st == "overdue" or secs < 0:
            return "overdue"
        if st in ("issued", "acked") and secs <= max(0, int(warn_seconds)):
            return "warn"
        return "ok"

    def effective_status(self):
        st = self.status or "issued"
        if st in ("issued", "acked") and self.return_by:
            rb = self._return_by_naive()
            if rb and rb < datetime.utcnow():
                return "overdue"
        return st

    def to_json(self, warn_seconds: int = 1800):
        return {
            "uid": self.uid,
            "mission_name": self.mission_name,
            "title": self.title,
            "body": self.body,
            "assignee": self.assignee,
            "sector_uid": self.sector_uid,
            "return_by": iso8601_string_from_datetime(self.return_by) if self.return_by else None,
            "status": self.effective_status(),
            "due_state": self.due_state(warn_seconds),
            "seconds_to_return": self.seconds_to_return(),
            "created_by": self.created_by,
            "created": iso8601_string_from_datetime(self.created) if self.created else None,
            "updated": iso8601_string_from_datetime(self.updated) if self.updated else None,
        }


