@dataclass
class MissionOpPeriod(db.Model):
    """Operational period / shift handoff for a SAR mission."""

    __tablename__ = "mission_op_periods"

    id: Mapped[int] = mapped_column(Integer, primary_key=True)
    uid: Mapped[str] = mapped_column(String(255), unique=True, nullable=False)
    mission_name: Mapped[str] = mapped_column(String(255), nullable=False)
    label: Mapped[str] = mapped_column(String(255), nullable=True)
    started_at: Mapped[datetime] = mapped_column(DateTime, nullable=False)
    ended_at: Mapped[datetime] = mapped_column(DateTime, nullable=True)
    status: Mapped[str] = mapped_column(String(32), nullable=False, default="open")
    commander: Mapped[str] = mapped_column(String(255), nullable=True)
    incoming_commander: Mapped[str] = mapped_column(String(255), nullable=True)
    summary: Mapped[str] = mapped_column(Text, nullable=True)
    findings: Mapped[str] = mapped_column(Text, nullable=True)
    next_priorities: Mapped[str] = mapped_column(Text, nullable=True)
    snapshot_json: Mapped[str] = mapped_column(Text, nullable=True)
    created_by: Mapped[str] = mapped_column(String(255), nullable=True)
    created: Mapped[datetime] = mapped_column(DateTime, nullable=True)
    updated: Mapped[datetime] = mapped_column(DateTime, nullable=True)

    def to_json(self, include_snapshot: bool = True):
        import json as _json

        out = {
            "uid": self.uid,
            "mission_name": self.mission_name,
            "label": self.label,
            "started_at": iso8601_string_from_datetime(self.started_at) if self.started_at else None,
            "ended_at": iso8601_string_from_datetime(self.ended_at) if self.ended_at else None,
            "status": self.status,
            "commander": self.commander,
            "incoming_commander": self.incoming_commander,
            "summary": self.summary,
            "findings": self.findings,
            "next_priorities": self.next_priorities,
            "created_by": self.created_by,
            "created": iso8601_string_from_datetime(self.created) if self.created else None,
            "updated": iso8601_string_from_datetime(self.updated) if self.updated else None,
            "has_snapshot": bool(self.snapshot_json),
        }
        if include_snapshot and self.snapshot_json:
            try:
                out["snapshot"] = _json.loads(self.snapshot_json)
            except Exception:
                out["snapshot"] = None
        return out

